import React, { useState, useEffect } from 'react';
import { FiSearch, FiUserCheck, FiUserX, FiPhone, FiMail, FiLoader } from 'react-icons/fi';
import { fetchProfiles } from '../api';
import './dashboard.css';

const PersonnelManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all');
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [personnel, setPersonnel] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadPersonnel = async () => {
      setLoading(true);
      setError(null);

      try {
        const profiles = await fetchProfiles();
        const mappedPersonnel = (profiles || []).map((profile) => ({
          id: profile.id,
          name: profile.full_name || profile.display_name || profile.email?.split('@')[0] || 'Unknown',
          email: profile.email || '',
          phone: profile.phone || '',
          role: profile.role || 'Member',
          status: profile.is_suspended ? 'suspended' : 'verified',
          rating: profile.rating ?? 0,
          jobs: profile.jobs ?? 0,
          followers: profile.followers ?? 0,
          bio: profile.bio || '',
          skills: profile.skills || [],
          avatar: profile.avatar_url || profile.avatar || null,
        }));

        setPersonnel(mappedPersonnel);
      } catch (fetchError) {
        console.error('[PersonnelManagement] Failed to load personnel:', fetchError);
        setError('Unable to load personnel from Supabase.');
      } finally {
        setLoading(false);
      }
    };

    loadPersonnel();
  }, []);

  const filteredPersonnel = personnel.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         p.email.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filter === 'all' || p.status === filter;
    return matchesSearch && matchesFilter;
  });

  const getStatusBadge = (status) => {
    const styles = {
      verified: { bg: '#00d973', text: 'Verified' },
      pending: { bg: '#ffd700', text: 'Pending' },
      suspended: { bg: '#ff6b6b', text: 'Suspended' },
    };
    return styles[status] || styles.verified;
  };

  return (
    <div className="panel">
      <div className="panel-title">Personnel Panel</div>
      
      {/* Error Message */}
      {error && (
        <div style={{ 
          padding: '12px 16px', 
          background: 'rgba(255, 107, 107, 0.1)', 
          border: '1px solid rgba(255, 107, 107, 0.3)', 
          borderRadius: 6, 
          color: '#ff6b6b',
          marginBottom: 16,
          fontSize: 13
        }}>
          ⚠️ {error}
        </div>
      )}
      
      {/* Summary Stats */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 20, flexWrap: 'wrap' }}>
        <div style={{ padding: '4px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Total Personnel</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#00d973' }}>{personnel.length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Verified</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#00d973' }}>{personnel.filter(p => p.status === 'verified').length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(255, 215, 0, 0.1)', border: '0.5px solid rgba(255, 215, 0, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Pending</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#ffd700' }}>{personnel.filter(p => p.status === 'pending').length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(255, 107, 107, 0.1)', border: '0.5px solid rgba(255, 107, 107, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Suspended</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#ff6b6b' }}>{personnel.filter(p => p.status === 'suspended').length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(0, 212, 255, 0.1)', border: '0.5px solid rgba(0, 212, 255, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Total Jobs</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#00d4ff' }}>{personnel.reduce((sum, p) => sum + p.jobs, 0)}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(255, 193, 7, 0.1)', border: '0.5px solid rgba(255, 193, 7, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Avg Rating</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#ffc107' }}>
            ⭐ {personnel.length > 0 ? (personnel.reduce((sum, p) => sum + p.rating, 0) / personnel.length).toFixed(1) : 0}
          </div>
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap', alignItems: 'center' }}>
        <div style={{ minWidth: 250, position: 'relative' }}>
          <FiSearch style={{ position: 'absolute', left: 8, top: '50%', transform: 'translateY(-50%)', color: '#8696a0' }} />
          <input
            type="text"
            placeholder="Search by name or email..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="input"
            style={{ 
              paddingLeft: 32, 
              width: '100%', 
              backgroundColor: 'black', 
              color: 'white', 
              fontSize: '13px',
              border: '1px solid transparent',
              borderRadius: '4px',
              transition: 'border-color 0.2s',
              outline: 'none'
            }}
          />
        </div>
        <select
          className="select"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ minWidth: 70, width: 'auto', fontSize: '10px' }}
        >
          <option value="all">All Status</option>
          <option value="verified">Verified</option>
          <option value="pending">Pending</option>
          <option value="suspended">Suspended</option>
        </select>
      </div>

      {/* Loading State */}
      {loading && (
        <div style={{ 
          display: 'flex', 
          justifyContent: 'center', 
          alignItems: 'center',
          padding: '40px 20px',
          fontSize: 14,
          color: '#8696a0'
        }}>
          <FiLoader style={{ animation: 'spin 1s linear infinite', marginRight: 8 }} />
          Loading personnel data...
        </div>
      )}
ake
      {/* Empty State */}
      {!loading && personnel.length === 0 && (
        <div style={{ 
          display: 'flex', 
          justifyContent: 'center', 
          alignItems: 'center',
          padding: '40px 20px',
          fontSize: 14,
          color: '#8696a0'
        }}>
          No personnel records found. Users who register as workers will appear here.
        </div>
      )}

      {/* Personnel Table */}
      {!loading && personnel.length > 0 && (
      <div style={{ overflowX: 'auto' }}>
        <table className="table">
          <thead>
            <tr>
              <th>#</th>
              <th>Name</th>
              <th>Email</th>
              <th>Phone</th>
              <th>Role / Title</th>
              <th>Status</th>
              <th>Rating</th>
              <th>Jobs Completed</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {filteredPersonnel.map((person, idx) => {
              const statusBadge = getStatusBadge(person.status);
              return (
                <tr key={person.id}>
                  <td style={{ width: '4%' }}>{idx + 1}</td>
                  <td style={{ width: '14%' }}><strong>{person.name}</strong></td>
                  <td style={{ width: '18%' }}>{person.email}</td>
                  <td style={{ width: '12%' }}>{person.phone}</td>
                  <td style={{ width: '12%' }}>{person.role}</td>
                  <td style={{ width: '10%' }}>
                    <span className="badge" style={{ color: statusBadge.bg, display: 'inline-flex', alignItems: 'center', gap: 4, padding: '4px 8px', borderRadius: 4, fontSize: 11 }}>
                      {statusBadge.text}
                    </span>
                  </td>
                  <td style={{ width: '8%', textAlign: 'center' }}>⭐ {person.rating.toFixed(1)}</td>
                  <td style={{ width: '10%', textAlign: 'center', fontWeight: 'bold', color: '#00d973' }}>{person.jobs}</td>
                  <td style={{ width: '12%', textAlign: 'center' }}>
                    <button
                      className="btn"
                      style={{ padding: '4px 8px', fontSize: '12px', whiteSpace: 'nowrap', width: 'auto', minWidth: 'auto', maxWidth: 'max-content' }}
                    >
                      Details
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      )}

      {/* Pagination Info */}
      {!loading && personnel.length > 0 && (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: 16, paddingTop: 12, borderTop: '1px solid rgba(134, 150, 160, 0.2)' }}>
        <div style={{ fontSize: 12, color: '#8696a0' }}>
          {filteredPersonnel.length} of {personnel.length} personnel
        </div>
      </div>
      )}
    </div>
  );
};

export default PersonnelManagement;
